let language = "nl";
let breathInterval = null;
let breathTimeout = null;
let toastTimeout = null;
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const t = key => translations[language][key] || translations.nl[key] || key;
function showToast(message) {
  const toast = $("#toast");
  toast.textContent = message;
  toast.classList.add("show");
  clearTimeout(toastTimeout);
  toastTimeout = setTimeout(() => toast.classList.remove("show"), 2800);
}
function setView(view) {
  $$(".view").forEach(section => section.classList.toggle("active", section.id === `view-${view}`));
  $$(".nav-item[data-view]").forEach(button => button.classList.toggle("active", button.dataset.view === view));
  $("#welcome").hidden = view !== "home";
  const heading = $(`#view-${view} h2`);
  if (heading) heading.setAttribute("tabindex", "-1");
  if (heading) heading.focus({preventScroll:true});
  window.scrollTo({top:0,behavior:document.body.classList.contains("reduced-motion") ? "auto" : "smooth"});
}
function updateTaskCount() {
  const checked = $$('[data-task]').filter(input => input.checked).length;
  $("#task-count").textContent = `${checked} / 3`;
  $("#progress-fill").style.width = `${checked / 3 * 100}%`;
}
function applyLanguage(next) {
  language = next === "en" ? "en" : "nl";
  document.documentElement.lang = language;
  $$("[data-i18n]").forEach(el => { const key = el.dataset.i18n; if (translations[language][key]) el.textContent = translations[language][key]; });
  $$("[data-i18n-placeholder]").forEach(el => { const key = el.dataset.i18nPlaceholder; if (translations[language][key]) el.placeholder = translations[language][key]; });
  $$("[data-i18n-aria-label]").forEach(el => { const key = el.dataset.i18nAriaLabel; if (translations[language][key]) el.setAttribute("aria-label", translations[language][key]); });
  $("#language").value = language;
  $("#language-settings").value = language;
  $("#language").setAttribute("aria-label", t("language"));
  renderCustomRoutines();
  updateVaultControls();
  $("[data-complete-routine]").forEach(button => { const done = button.dataset.done === "true"; button.textContent = done ? t("routineMarkedDone") : t("routineMarkDone"); });
  $("#today-date").textContent = new Intl.DateTimeFormat(language === "nl" ? "nl-NL" : "en-GB", {weekday:"short",day:"numeric",month:"short"}).format(new Date());
  $("#task-status").textContent = "";
  $("#routine-status").textContent = "";
  $$("[data-routine-step]").forEach(input => updateRoutineProgress(input.dataset.routineStep));
  $("#breath-word").textContent = t("ready");
  $("#breath-instruction").textContent = t("breathIntro");
}

const customRoutineStorageKey = "project-n-01-custom-routines-v1";
const encryptedVaultStorageKey = "project-n-01-encrypted-vault-v1";
let activeVault = null;
let encryptedVaultExists = localStorage.getItem(encryptedVaultStorageKey) !== null;
let customRoutines = encryptedVaultExists ? [] : readCustomRoutines();

function updateVaultControls() {
  const locked = encryptedVaultExists && !(activeVault && activeVault.isUnlocked);
  $("#custom-routine-form").querySelectorAll("input, textarea, button").forEach(control => { control.disabled = locked; });
  ["#clear-custom-routines", "#export-custom-routines", "#import-custom-routines", "#export-encrypted-routines", "#import-encrypted-routines"]
    .forEach(selector => { const control = $(selector); if (control) control.disabled = locked; });
  $("#lock-encrypted-vault").disabled = !activeVault || !activeVault.isUnlocked;
  $("#delete-plaintext-routines").hidden = !activeVault || !activeVault.isUnlocked || localStorage.getItem(customRoutineStorageKey) === null;
  const routinePrivacy = document.querySelector('[data-i18n="customRoutinePrivacy"]');
  if (routinePrivacy) routinePrivacy.textContent = encryptedVaultExists && !locked ? t("vaultRoutinePrivacy") : encryptedVaultExists ? t("vaultLockedPrivacy") : t("customRoutinePrivacy");
}
let vaultAutoLockTimer = null;
const VAULT_AUTO_LOCK_MS = 5 * 60 * 1000;
function lockVaultSession(message = t("vaultLockedStatus")) {
  if (vaultAutoLockTimer !== null) window.clearTimeout(vaultAutoLockTimer);
  vaultAutoLockTimer = null;
  if (activeVault) activeVault.lock();
  activeVault = null;
  if (encryptedVaultExists) customRoutines = [];
  updateVaultControls();
  renderCustomRoutines();
  $("#vault-migration-status").textContent = message;
}
function scheduleVaultAutoLock() {
  if (vaultAutoLockTimer !== null) window.clearTimeout(vaultAutoLockTimer);
  vaultAutoLockTimer = null;
  if (!activeVault || !activeVault.isUnlocked) return;
  vaultAutoLockTimer = window.setTimeout(() => lockVaultSession(t("vaultAutoLock")), VAULT_AUTO_LOCK_MS);
}
["pointerdown", "keydown", "touchstart", "scroll"].forEach(eventName => {
  document.addEventListener(eventName, () => {
    if (activeVault && activeVault.isUnlocked) scheduleVaultAutoLock();
  }, { passive: true });
});
document.addEventListener("visibilitychange", () => {
  if (document.visibilityState === "hidden" && activeVault && activeVault.isUnlocked) {
    lockVaultSession(t("vaultAutoLock"));
  }
});
window.addEventListener("pagehide", () => {
  if (activeVault) activeVault.lock();
  activeVault = null;
  if (vaultAutoLockTimer !== null) window.clearTimeout(vaultAutoLockTimer);
  vaultAutoLockTimer = null;
});

function readCustomRoutines() {
  try {
    const value = JSON.parse(localStorage.getItem(customRoutineStorageKey) || "[]");
    if (!Array.isArray(value)) return [];
    return value.filter(item => item && typeof item.id === "string" && typeof item.name === "string" && Array.isArray(item.steps))
      .map(item => ({id:item.id, name:item.name.slice(0,60), steps:item.steps.filter(step => typeof step === "string").slice(0,10).map(step => step.slice(0,120))}));
  } catch { return []; }
}
async function saveCustomRoutines() {
  try {
    if (encryptedVaultExists) {
      if (!activeVault || !activeVault.isUnlocked) throw new Error("vault-locked");
      await activeVault.save({ routines: customRoutines });
    } else {
      localStorage.setItem(customRoutineStorageKey, JSON.stringify(customRoutines));
    }
    return true;
  } catch {
    $("#custom-routine-status").textContent = t("customRoutineStorageError");
    return false;
  }
}
function renderCustomRoutines() {
  const list = $("#custom-routine-list");
  if (!list) return;
  list.replaceChildren();
  if (!customRoutines.length) {
    const empty = document.createElement("p");
    empty.className = "privacy-hint";
    empty.textContent = encryptedVaultExists && !(activeVault && activeVault.isUnlocked) ? t("vaultLocked") : t("customRoutineEmpty");
    list.append(empty);
    return;
  }
  customRoutines.forEach(routine => {
    const card = document.createElement("article");
    card.className = "routine-card custom-routine-card";
    const heading = document.createElement("h4");
    heading.textContent = routine.name;
    card.append(heading);
    const stepsList = document.createElement("ol");
    routine.steps.forEach((step, index) => {
      const item = document.createElement("li");
      const label = document.createElement("label");
      label.className = "routine-step";
      const checkbox = document.createElement("input");
      checkbox.type = "checkbox";
      checkbox.dataset.customRoutineStep = routine.id;
      checkbox.setAttribute("aria-label", step);
      const text = document.createElement("span");
      text.textContent = step;
      label.append(checkbox, text);
      item.append(label);
      stepsList.append(item);
    });
    const progress = document.createElement("p");
    progress.className = "routine-progress";
    progress.setAttribute("role", "status");
    progress.setAttribute("aria-live", "polite");
    const updateProgress = () => {
      const checks = [...stepsList.querySelectorAll('input[type="checkbox"]')];
      const done = checks.filter(check => check.checked).length;
      progress.textContent = t("routineProgress").replace("{done}", String(done)).replace("{total}", String(checks.length));
    };
    stepsList.addEventListener("change", updateProgress);
    card.append(stepsList, progress);
    const remove = document.createElement("button");
    remove.type = "button";
    remove.className = "secondary-button";
    remove.textContent = t("customRoutineDelete");
    remove.addEventListener("click", async () => {
      const previous = customRoutines;
      customRoutines = customRoutines.filter(item => item.id !== routine.id);
      if (!(await saveCustomRoutines())) { customRoutines = previous; return; }
      renderCustomRoutines();
      $("#custom-routine-status").textContent = t("customRoutineDeleted");
    });
    card.append(remove);
    list.append(card);
    updateProgress();
  });
}
$("#custom-routine-form").addEventListener("submit", async event => {
  event.preventDefault();
  const name = $("#custom-routine-name").value.trim();
  const steps = $("#custom-routine-steps").value.split(/\r?\n/).map(step => step.trim()).filter(Boolean).slice(0,10);
  if (!name || !steps.length) {
    $("#custom-routine-status").textContent = t("customRoutineInvalid");
    return;
  }
  customRoutines.push({id: `routine-${Date.now()}-${Math.random().toString(36).slice(2,8)}`, name:name.slice(0,60), steps:steps.map(step=>step.slice(0,120))});
  if (!(await saveCustomRoutines())) {
    customRoutines.pop();
    return;
  }
  $("#custom-routine-form").reset();
  renderCustomRoutines();
  $("#custom-routine-status").textContent = t("customRoutineAdded");
});
renderCustomRoutines();
updateVaultControls();

function normaliseImportedRoutines(value) {
  if (!Array.isArray(value)) return [];
  return value.filter(item => item && typeof item.name === "string" && Array.isArray(item.steps))
    .map((item, index) => ({
      id: `import-${Date.now()}-${index}-${Math.random().toString(36).slice(2,7)}`,
      name: item.name.trim().slice(0,60),
      steps: item.steps.filter(step => typeof step === "string").map(step => step.trim()).filter(Boolean).slice(0,10).map(step => step.slice(0,120))
    }))
    .filter(item => item.name && item.steps.length)
    .slice(0,50);
}
